import {ABYSS_SITE,ABYSS_NAME} from './abyss-model.js';
import {SECRET_SITE} from './underground-model.js';
import {ADVENTURES} from './places.js';
export const CRYSTAL_ORDER=[0,2,1];
export function restoreAdventure(value){const state={visited:[],completed:[],crystals:{},rituals:{},secretOpened:false,clanMet:false,forgeLit:false,bellRung:false,abyssRunes:[],abyssOpened:false,ancientMet:false};if(!value||typeof value!=='object')return state;state.abyssRunes=Array.isArray(value.abyssRunes)?[...new Set(value.abyssRunes.filter(i=>i===0||i===1))]:[];state.abyssOpened=value.abyssOpened===true&&state.abyssRunes.length===2;state.ancientMet=state.abyssOpened&&value.ancientMet===true;state.secretOpened=value.secretOpened===true;for(const field of ['clanMet','forgeLit','bellRung'])state[field]=state.secretOpened&&value[field]===true;const ids=ADVENTURES.map(s=>s.id);for(const field of ['visited','completed'])state[field]=Array.isArray(value[field])?[...new Set(value[field].filter(id=>ids.includes(id)))]:[];for(const site of ADVENTURES){state.crystals[site.id]=[];state.rituals[site.id]=Array.isArray(value.rituals?.[site.id])?[...new Set(value.rituals[site.id].filter(a=>['fire','drum','totem'].includes(a)))]:[];}return state;}
export function adventureAction(state,id,action,index=0){const site=ADVENTURES.find(s=>s.id===id);if(!site)return{message:'Lugar desconhecido.'};if(!state.visited.includes(id))state.visited.push(id);
 if(action==='abyss-rune'&&id===ABYSS_SITE&&(index===0||index===1)){if(!state.abyssRunes.includes(index))state.abyssRunes.push(index);return{message:state.abyssRunes.length===2?'As duas marcas respondem. Uma fissura fria aguarda no fim de uma galeria lateral.':'A marca guarda metade de um nome. Procure sua irmã entre as escoras esquecidas.'};}
 if(action==='abyss-seal'&&id===ABYSS_SITE){if(state.abyssRunes.length<2)return{message:'A pedra está fria. Duas marcas antigas parecem faltar ao selo.'};state.abyssOpened=true;return{message:'O selo cede. Uma passagem sem trilhos desce até uma câmara esquecida.'};}
 if(action==='ancient'&&id===ABYSS_SITE&&state.abyssOpened){state.ancientMet=true;return{message:`${ABYSS_NAME}: Antes das minas, antes dos nomes, eu já velava o caos. As brasas se agitam dentro do círculo de contenção.`};}
 if(action==='secret'&&id===SECRET_SITE){state.secretOpened=true;return{message:'A pedra cede ao seu toque. A magia branca milenar revela uma senda que os goblins não conseguem perceber.',pulse:true};}
 if(action==='mine-journal')return{message:'Caderno de turno: «Trilhos cedidos. Duas marcas frias: uma na galeria lateral, outra entre escoras. Não seguimos a fissura. O último turno nunca voltou.»'};
 if(['dwarf','forge','clan-bell'].includes(action)&&id===SECRET_SITE&&state.secretOpened){state.clanMet=true;if(action==='forge')state.forgeLit=true;if(action==='clan-bell')state.bellRung=true;return{message:action==='forge'?'A forja ancestral desperta. Os anões retomam o ritmo dos martelos.':action==='clan-bell'?'O sino ressoa sob a terra. O Clã da Pedra Milenar reconhece sua visita.':'O clã recebe você entre suas antigas galerias.',pulse:true};}
 if(action==='greet')return{message:site.kind==='cave'?'Brilha! Verde, violeta, azul! Esses abrem o relicário. A gente passeia pelas minas atrás de pedrinhas; pedra sem brilho não tem graça.':'A guardiã sorri: desperte a fogueira, toque o tambor e gire o totem. Cada gesto acrescenta uma camada ao círculo.'};
 if(action==='crystal'&&site.kind==='cave'){if(state.completed.includes(id))return{message:'Os cristais já estão em harmonia. O relicário permanece aberto.'};const sequence=state.crystals[id]||[];if(index!==CRYSTAL_ORDER[sequence.length]){state.crystals[id]=[];return{message:'A ressonância se desfez. Recomece: verde → violeta → azul.',pulse:true};}sequence.push(index);state.crystals[id]=sequence;if(sequence.length===3){state.completed.push(id);return{message:'O relicário se abriu! Você harmonizou os ecos da caverna.',pulse:true,complete:true};}return{message:`Cristal ${sequence.length}/3 em harmonia. Próximo: ${sequence.length===1?'violeta':'azul'}.`,pulse:true};}
 if(site.kind==='village'&&['fire','drum','totem'].includes(action)){const list=state.rituals[id]||(state.rituals[id]=[]);if(!list.includes(action))list.push(action);const complete=list.length===3;if(complete&&!state.completed.includes(id))state.completed.push(id);return{message:complete?'O círculo está completo. Fogueira, tambor e totem desenham juntos.':`${list.length}/3 elementos despertos. Experimente os outros objetos do círculo.`,pulse:true,complete};}
 return{message:'Explore os objetos luminosos deste lugar.'};
}
